38	    /**
39	     * Derives the owner's {@code selfLink}: the canonical API path {@code /api/owners/} followed by
40	     * the owner's id. Returns null when the owner has no id (e.g. before it has been persisted).
41	     */
42	    default String toSelfLink(Owner owner) {
43	        if (owner.getId() == null) {
44	            return null;
45	        }
46	        return "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * Derives the owner's {@code fiscalYear}: the fiscal year of the business-day-adjusted
51	     * {@code registrationDate}, formatted {@code FY<YY>} (see
52	     * {@link org.springframework.samples.petclinic.rest.function.owner.FiscalYear}). Returns null
53	     * when no registration date is present (e.g. unmigrated seed data).
54	     */
55	    default String toFiscalYear(Owner owner) {
56	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
57	        if (registrationDate == null) {
58	            return null;
59	        }
60	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
61	    }
62	
63	    /**
64	     * Derives the owner's {@code salutation}: the {@code title} followed by a single space and the
65	     * {@code lastName} when a title is present, or just the {@code lastName} when no title was
66	     * supplied.
67	     */
68	    default String toSalutation(Owner owner) {
69	        String title = owner.getTitle();
70	        if (title == null || title.isBlank()) {
71	            return owner.getLastName();
72	        }
73	        return title + " " + owner.getLastName();
74	    }
