86	    /**
87	     * Derives the owner's {@code ageBand} from its {@code birthDate} measured against its
88	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64,
89	     * {@code SENIOR} at 65 or older. Returns null when either date is absent (so no band is
90	     * reported for owners with no supplied birth date).
91	     */
92	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
93	        java.time.LocalDate birthDate = owner.getBirthDate();
94	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
95	        if (birthDate == null || registrationDate == null) {
96	            return null;
97	        }
98	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
99	        if (age < 18) {
100	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
101	        }
102	        if (age < 65) {
103	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
104	        }
105	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
