203	     * before any household cap: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
204	     */
205	    default Integer deriveMembershipLevel(Owner owner) {
206	        int points = toMembershipPoints(owner);
207	        if (points >= 6) {
208	            return 4;
209	        }
210	        if (points >= 4) {
211	            return 3;
212	        }
213	        if (points >= 2) {
214	            return 2;
215	        }
216	        return 1;
217	    }
218	
219	    /**
220	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
221	     * last two digits of the fiscal year of the registration date (fiscal years starting 1 July;
222	     * e.g. {@code NSW-1A2B3C4D-M26}). Returns null when either the customer code or registration
223	     * date is absent (e.g. unmigrated seed data).
224	     */
225	    default String toMembershipNumber(Owner owner) {
226	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
227	            return null;
228	        }
229	        int fiscalYear = org.springframework.samples.petclinic.rest.function.owner.FiscalYear
230	                .of(owner.getRegistrationDate());
231	        return owner.getCustomerCode() + "-M" + String.format("%02d", fiscalYear % 100);
232	    }
233	
234	    /**
235	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the
236	     * digits contained in the {@code customerCode}. Returns null when the customer code is
237	     * absent (e.g. unmigrated seed data).
238	     */
239	    default Integer toCheckDigit(Owner owner) {
240	        String customerCode = owner.getCustomerCode();
241	        if (customerCode == null) {
242	            return null;
243	        }
244	        int sum = 0;
245	        boolean dbl = true;
246	        for (int i = customerCode.length() - 1; i >= 0; i--) {
247	            char c = customerCode.charAt(i);
248	            if (c < '0' || c > '9') {
249	                continue;
250	            }
251	            int d = c - '0';
252	            if (dbl) {
253	                d *= 2;
254	                if (d > 9) {
255	                    d -= 9;
256	                }
257	            }
258	            sum += d;
259	            dbl = !dbl;
260	        }
261	        return (10 - (sum % 10)) % 10;
262	    }
